#!/bin/bash

RCM_EXTENSION_VERSION=0.19.0-alpha.8

# Usage Functions.
usage() {
    cat << EOF
Usage: rcm-system-ram-swap-4gb [options]

Global Options:
   --version
        Print version of this script.
   --help
        Show this help.
EOF
}

[ -f "${RCM_LIB}/require.sh" ] && source "${RCM_LIB}/require.sh" || { usage >&2; exit 1; }

# Parse arguments. Generated by parse-options.sh.
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help) help=1; shift ;;
        --version) version=1; shift ;;
        --[^-]*) shift ;;
        *) _new_arguments+=("$1"); shift ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments

# Define variables and constants.

# Help and Version.
[ -n "$help" ] && { usage; exit 0; }
[ -n "$version" ] && { e $RCM_EXTENSION_VERSION; x; }

# ------------------------------------------------------------------------------

# Title.
title rcm-system-ram-swap-4gb
____

# Dependency.

path=/swapfile-rcm-4G

chapter Membuat file swap.
code fallocate -l 4G "$path"
code chmod 600 "$path"
code mkswap "$path"
____

if [ ! -f "$path" ];then
    fallocate -l 4G "$path"
    chmod 600 "$path"
    mkswap "$path"
fi
chapter Mengaktifkan file swap.
if grep -q "^${path}$" <<< `swapon --show=name --noheadings --raw`;then
    code swapon "$path"
else
    code swapon "$path"
    swapon "$path"
fi
____

exit 0

